import * as assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import { SetCookie } from './set-cookie.js';

describe('SetCookie', () => {
  it('parses initial value correctly', () => {
    let header = new SetCookie(
      'session=abc123; Domain=example.com; Path=/; Expires=Wed, 21 Oct 2015 07:28:00 GMT; Secure; HttpOnly'
    );
    assert.equal(header.name, 'session');
    assert.equal(header.value, 'abc123');
    assert.equal(header.domain, 'example.com');
    assert.equal(header.path, '/');
    assert.equal(header.expires?.toUTCString(), 'Wed, 21 Oct 2015 07:28:00 GMT');
    assert.equal(header.secure, true);
    assert.equal(header.httpOnly, true);
  });

  it('handles cookies without attributes', () => {
    let header = new SetCookie('user=john');
    assert.equal(header.name, 'user');
    assert.equal(header.value, 'john');
  });

  it('initializes with an empty string', () => {
    let header = new SetCookie('');
    assert.equal(header.name, undefined);
    assert.equal(header.value, undefined);
  });

  it('handles cookie values with commas', () => {
    let header = new SetCookie('list=apple,banana,cherry; Domain=example.com');
    assert.equal(header.name, 'list');
    assert.equal(header.value, 'apple,banana,cherry');
    assert.equal(header.domain, 'example.com');
  });

  it('handles cookie values with semicolons', () => {
    let header = new SetCookie('complex="value; with; semicolons"; Path=/');
    assert.equal(header.name, 'complex');
    assert.equal(header.value, 'value; with; semicolons');
    assert.equal(header.path, '/');
  });

  it('handles cookie values with equals signs', () => {
    let header = new SetCookie('equation="1+1=2"; Secure');
    assert.equal(header.name, 'equation');
    assert.equal(header.value, '1+1=2');
    assert.equal(header.secure, true);
  });

  it('sets and gets attributes', () => {
    let header = new SetCookie('test=value');
    header.domain = 'example.org';
    header.path = '/api';
    header.maxAge = 3600;
    header.secure = true;
    header.httpOnly = true;
    header.sameSite = 'Strict';

    assert.equal(header.domain, 'example.org');
    assert.equal(header.path, '/api');
    assert.equal(header.maxAge, 3600);
    assert.equal(header.secure, true);
    assert.equal(header.httpOnly, true);
    assert.equal(header.sameSite, 'Strict');
  });

  it('converts to string correctly', () => {
    let header = new SetCookie('session=abc123');
    header.domain = 'example.com';
    header.path = '/';
    header.secure = true;
    header.httpOnly = true;
    header.sameSite = 'Lax';

    assert.equal(
      header.toString(),
      'session=abc123; Domain=example.com; Path=/; Secure; HttpOnly; SameSite=Lax'
    );
  });

  it('converts to an empty string when name is not set', () => {
    let header = new SetCookie();
    header.value = 'test';
    assert.equal(header.toString(), '');
  });

  it('handles quoted values', () => {
    let header = new SetCookie('complex="quoted value; with semicolon"');
    assert.equal(header.name, 'complex');
    assert.equal(header.value, 'quoted value; with semicolon');
  });

  it('parses and formats expires attribute correctly', () => {
    let expiresDate = new Date('Wed, 21 Oct 2015 07:28:00 GMT');
    let header = new SetCookie(`test=value; Expires=${expiresDate.toUTCString()}`);
    assert.equal(header.expires?.toUTCString(), expiresDate.toUTCString());

    header.expires = new Date('Thu, 22 Oct 2015 07:28:00 GMT');
    assert.equal(header.toString(), 'test=value; Expires=Thu, 22 Oct 2015 07:28:00 GMT');
  });

  it('handles SameSite attribute case-insensitively', () => {
    let header = new SetCookie('test=value; SameSite=lax');
    assert.equal(header.sameSite, 'Lax');

    header = new SetCookie('test=value; SameSite=STRICT');
    assert.equal(header.sameSite, 'Strict');

    header = new SetCookie('test=value; SameSite=NoNe');
    assert.equal(header.sameSite, 'None');
  });

  it('handles cookies with empty value', () => {
    let header = new SetCookie('name=');
    assert.equal(header.name, 'name');
    assert.equal(header.value, '');
  });

  it('handles multiple identical attributes', () => {
    let header = new SetCookie('test=value; Path=/; Path=/api');
    assert.equal(header.path, '/api');
  });

  it('ignores unknown attributes', () => {
    let header = new SetCookie('test=value; Unknown=something');
    assert.equal(header.toString(), 'test=value');
  });

  it('handles Max-Age as a number', () => {
    let header = new SetCookie('test=value; Max-Age=3600');
    assert.equal(header.maxAge, 3600);
  });

  it('ignores invalid Max-Age', () => {
    let header = new SetCookie('test=value; Max-Age=invalid');
    assert.equal(header.maxAge, undefined);
  });

  it('handles missing value in attributes', () => {
    let header = new SetCookie('test=value; Domain=; Path');
    assert.equal(header.domain, '');
    assert.equal(header.path, undefined);
  });

  it('preserves the case of the cookie name and value', () => {
    let header = new SetCookie('TestName=TestValue');
    assert.equal(header.name, 'TestName');
    assert.equal(header.value, 'TestValue');
  });

  it('handles setting new name and value', () => {
    let header = new SetCookie('old=value');
    header.name = 'new';
    header.value = 'newvalue';
    assert.equal(header.toString(), 'new=newvalue');
  });

  it('correctly quotes values when necessary', () => {
    let header = new SetCookie('test=value');
    header.value = 'need; quotes';
    assert.equal(header.toString(), 'test="need; quotes"');
  });
});

import * as assert from "node:assert/strict";
import { describe, it } from "node:test";

import { Cookie } from "./cookie.js";

describe("Cookie", () => {
  it("parses initial value correctly", () => {
    let header = new Cookie("name1=value1; name2=value2");
    assert.equal(header.get("name1"), "value1");
    assert.equal(header.get("name2"), "value2");
  });

  it("handles empty initial value", () => {
    let header = new Cookie("");
    assert.equal(header.size, 0);
  });

  it("handles whitespace in initial value", () => {
    let header = new Cookie(" name1 = value1 ;  name2  =  value2 ");
    assert.equal(header.get("name1"), "value1");
    assert.equal(header.get("name2"), "value2");
  });

  it("sets and gets values", () => {
    let header = new Cookie("");
    header.set("name", "value");
    assert.equal(header.get("name"), "value");
  });

  it("deletes values", () => {
    let header = new Cookie("name=value");
    assert.equal(header.delete("name"), true);
    assert.equal(header.delete("nonexistent"), false);
    assert.equal(header.get("name"), undefined);
  });

  it("checks if value exists", () => {
    let header = new Cookie("name=value");
    assert.equal(header.has("name"), true);
    assert.equal(header.has("nonexistent"), false);
  });

  it("clears all values", () => {
    let header = new Cookie("name1=value1; name2=value2");
    header.clear();
    assert.equal(header.size, 0);
  });

  it("iterates over entries", () => {
    let header = new Cookie("name1=value1; name2=value2");
    let entries = Array.from(header.entries());
    assert.deepEqual(entries, [
      ["name1", "value1"],
      ["name2", "value2"]
    ]);
  });

  it("iterates over names", () => {
    let header = new Cookie("name1=value1; name2=value2");
    let names = Array.from(header.names());
    assert.deepEqual(names, ["name1", "name2"]);
  });

  it("iterates over values", () => {
    let header = new Cookie("name1=value1; name2=value2");
    let values = Array.from(header.values());
    assert.deepEqual(values, ["value1", "value2"]);
  });

  it("uses forEach correctly", () => {
    let header = new Cookie("name1=value1; name2=value2");
    let result: [string, string][] = [];
    header.forEach((value, name) => {
      result.push([name, value]);
    });
    assert.deepEqual(result, [
      ["name1", "value1"],
      ["name2", "value2"]
    ]);
  });

  it("returns correct size", () => {
    let header = new Cookie("name1=value1; name2=value2");
    assert.equal(header.size, 2);
  });

  it("converts to string correctly", () => {
    let header = new Cookie("name1=value1; name2=value2");
    assert.equal(header.toString(), "name1=value1; name2=value2");
  });

  it("is directly iterable", () => {
    let header = new Cookie("name1=value1; name2=value2");
    let entries = Array.from(header);
    assert.deepEqual(entries, [
      ["name1", "value1"],
      ["name2", "value2"]
    ]);
  });

  it("handles cookies without values", () => {
    let header = new Cookie("name1=value1; name2");
    assert.equal(header.get("name1"), "value1");
    assert.equal(header.get("name2"), "");
  });

  it("handles setting empty values", () => {
    let header = new Cookie("");
    header.set("name", "");
    assert.equal(header.get("name"), "");
    assert.equal(header.toString(), "name=");
  });

  it("overwrites existing values", () => {
    let header = new Cookie("name=value1");
    header.set("name", "value2");
    assert.equal(header.get("name"), "value2");
  });
});

import * as assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import { ContentType } from './content-type.js';

describe('ContentType', () => {
  it('parses initial value correctly', () => {
    let header = new ContentType('text/plain; charset=utf-8');
    assert.equal(header.mediaType, 'text/plain');
    assert.equal(header.charset, 'utf-8');
  });

  it('handles empty initial value', () => {
    let header = new ContentType('');
    assert.equal(header.mediaType, undefined);
    assert.equal(header.charset, undefined);
  });

  it('handles whitespace in initial value', () => {
    let header = new ContentType(' text/html ;  charset = iso-8859-1 ');
    assert.equal(header.mediaType, 'text/html');
    assert.equal(header.charset, 'iso-8859-1');
  });

  it('sets and gets media type', () => {
    let header = new ContentType('text/plain');
    header.mediaType = 'application/json';
    assert.equal(header.mediaType, 'application/json');
  });

  it('sets and gets charset', () => {
    let header = new ContentType('text/plain');
    header.charset = 'utf-8';
    assert.equal(header.charset, 'utf-8');
  });

  it('sets and gets boundary', () => {
    let header = new ContentType('multipart/form-data');
    header.boundary = 'abc123';
    assert.equal(header.boundary, 'abc123');
  });

  it('handles quoted attribute values', () => {
    let header = new ContentType('text/plain; charset="us-ascii"');
    assert.equal(header.charset, 'us-ascii');
  });

  it('converts to string correctly', () => {
    let header = new ContentType('text/plain; charset=utf-8');
    assert.equal(header.toString(), 'text/plain; charset=utf-8');
  });

  it('converts to an empty string when media type is not set', () => {
    let header = new ContentType();
    header.charset = 'utf-8';
    assert.equal(header.toString(), '');
  });

  it('handles multiple attributes', () => {
    let header = new ContentType('multipart/form-data; boundary="abc123"; charset=utf-8');
    assert.equal(header.mediaType, 'multipart/form-data');
    assert.equal(header.boundary, 'abc123');
    assert.equal(header.charset, 'utf-8');
  });

  it('preserves case for media type', () => {
    let header = new ContentType('Text/HTML');
    assert.equal(header.mediaType, 'Text/HTML');
  });

  it('handles attribute values with special characters', () => {
    let header = new ContentType('multipart/form-data; boundary="---=_Part_0_1234567.89"');
    assert.equal(header.boundary, '---=_Part_0_1234567.89');
  });

  it('correctly quotes attribute values in toString()', () => {
    let header = new ContentType('multipart/form-data');
    header.boundary = 'abc 123';
    assert.equal(header.toString(), 'multipart/form-data; boundary="abc 123"');
  });

  it('handles empty attribute values', () => {
    let header = new ContentType('text/plain; charset=');
    assert.equal(header.charset, '');
  });

  it('ignores attributes without values', () => {
    let header = new ContentType('text/plain; charset');
    assert.equal(header.charset, undefined);
  });

  it('preserves order of attributes in toString()', () => {
    let header = new ContentType('multipart/form-data; charset=utf-8; boundary=abc123');
    assert.equal(header.toString(), 'multipart/form-data; charset=utf-8; boundary=abc123');
  });
});

import * as assert from 'node:assert/strict';
import { describe, it } from 'node:test';

import { ContentDisposition } from './content-disposition.js';

describe('ContentDisposition', () => {
  it('parses initial value correctly', () => {
    let header = new ContentDisposition('attachment; filename="example.txt"');
    assert.equal(header.type, 'attachment');
    assert.equal(header.filename, 'example.txt');
  });

  it('handles empty initial value', () => {
    let header = new ContentDisposition('');
    assert.equal(header.type, undefined);
    assert.equal(header.filename, undefined);
  });

  it('handles whitespace in initial value', () => {
    let header = new ContentDisposition(' inline ;  filename = "document.pdf" ');
    assert.equal(header.type, 'inline');
    assert.equal(header.filename, 'document.pdf');
  });

  it('sets and gets type', () => {
    let header = new ContentDisposition('attachment');
    header.type = 'inline';
    assert.equal(header.type, 'inline');
  });

  it('sets and gets filename', () => {
    let header = new ContentDisposition('attachment');
    header.filename = 'example.txt';
    assert.equal(header.filename, 'example.txt');
  });

  it('sets and gets name', () => {
    let header = new ContentDisposition('form-data');
    header.name = 'field1';
    assert.equal(header.name, 'field1');
  });

  it('sets and gets filenameSplat', () => {
    let header = new ContentDisposition('attachment');
    header.filenameSplat = "UTF-8''%E6%96%87%E4%BB%B6.txt";
    assert.equal(header.filenameSplat, "UTF-8''%E6%96%87%E4%BB%B6.txt");
  });

  it('handles quoted attribute values', () => {
    let header = new ContentDisposition('attachment; filename="file with spaces.txt"');
    assert.equal(header.filename, 'file with spaces.txt');
  });

  it('converts to string correctly', () => {
    let header = new ContentDisposition('attachment; filename="example.txt"');
    assert.equal(header.toString(), 'attachment; filename=example.txt');
  });

  it('converts to an empty string when type is not set', () => {
    let header = new ContentDisposition();
    header.filename = 'example.txt';
    assert.equal(header.toString(), '');
  });

  it('handles multiple attributes', () => {
    let header = new ContentDisposition('form-data; name="field1"; filename="example.txt"');
    assert.equal(header.type, 'form-data');
    assert.equal(header.name, 'field1');
    assert.equal(header.filename, 'example.txt');
  });

  it('preserves case for type', () => {
    let header = new ContentDisposition('Attachment');
    assert.equal(header.type, 'Attachment');
  });

  it('handles attribute values with special characters', () => {
    let header = new ContentDisposition(
      'attachment; filename="file with spaces and (parentheses).txt"'
    );
    assert.equal(header.filename, 'file with spaces and (parentheses).txt');
  });

  it('correctly quotes attribute values in toString()', () => {
    let header = new ContentDisposition('attachment');
    header.filename = 'file "with" quotes.txt';
    assert.equal(header.toString(), 'attachment; filename="file \\"with\\" quotes.txt"');
  });

  it('handles empty attribute values', () => {
    let header = new ContentDisposition('form-data; name=');
    assert.equal(header.name, '');
  });

  it('ignores attributes without values', () => {
    let header = new ContentDisposition('attachment; filename');
    assert.equal(header.filename, undefined);
  });

  it('preserves order of attributes in toString()', () => {
    let header = new ContentDisposition('form-data; name="field1"; filename="example.txt"');
    assert.equal(header.toString(), 'form-data; name=field1; filename=example.txt');
  });

  it('handles filename* (RFC 5987) correctly', () => {
    let header = new ContentDisposition("attachment; filename*=UTF-8''%E6%96%87%E4%BB%B6.txt");
    assert.equal(header.filenameSplat, "UTF-8''%E6%96%87%E4%BB%B6.txt");
  });

  it('prioritizes filename* over filename when both are present', () => {
    let header = new ContentDisposition(
      'attachment; filename="fallback.txt"; filename*=UTF-8\'\'%E6%96%87%E4%BB%B6.txt'
    );
    assert.equal(header.filename, 'fallback.txt');
    assert.equal(header.filenameSplat, "UTF-8''%E6%96%87%E4%BB%B6.txt");
  });

  it('handles form-data disposition type correctly', () => {
    let header = new ContentDisposition('form-data; name="uploadedfile"; filename="example.txt"');
    assert.equal(header.type, 'form-data');
    assert.equal(header.name, 'uploadedfile');
    assert.equal(header.filename, 'example.txt');
  });

  describe('preferredFilename', () => {
    it('returns filename* when both filename and filename* are present', () => {
      let header = new ContentDisposition(
        'attachment; filename="old.txt"; filename*=UTF-8\'\'new.txt'
      );
      assert.equal(header.preferredFilename, 'new.txt');
    });

    it('returns filename when only filename is present', () => {
      let header = new ContentDisposition('attachment; filename="document.pdf"');
      assert.equal(header.preferredFilename, 'document.pdf');
    });

    it('returns filename* when only filename* is present', () => {
      let header = new ContentDisposition("attachment; filename*=UTF-8''special%20file.txt");
      assert.equal(header.preferredFilename, 'special file.txt');
    });

    it('handles UTF-8 encoded filename* with special characters', () => {
      let header = new ContentDisposition("attachment; filename*=UTF-8''%E6%96%87%E4%BB%B6.txt");
      assert.equal(header.preferredFilename, '文件.txt');
    });

    it('handles ISO-8859-1 encoded filename* with special characters', () => {
      let header = new ContentDisposition("attachment; filename*=ISO-8859-1''f%F6o.txt");
      assert.equal(header.preferredFilename, 'föo.txt');
    });

    it('handles filename* with spaces and other special characters', () => {
      let header = new ContentDisposition(
        "attachment; filename*=UTF-8''hello%20world%21%20%26%20goodbye.txt"
      );
      assert.equal(header.preferredFilename, 'hello world! & goodbye.txt');
    });

    it('returns undefined when no filename or filename* is present', () => {
      let header = new ContentDisposition('attachment');
      assert.equal(header.preferredFilename, undefined);
    });

    it('falls back to filename when filename* is invalid', () => {
      let header = new ContentDisposition('attachment; filename="fallback.txt"; filename*=invalid');
      assert.equal(header.preferredFilename, 'fallback.txt');
    });

    it('correctly decodes ISO-8859-1 encoded filename', () => {
      let header = new ContentDisposition("attachment; filename*=ISO-8859-1''f%F6o.txt");
      assert.equal(header.preferredFilename, 'föo.txt');
    });

    it('correctly decodes ISO-8859-15 encoded filename', () => {
      let header = new ContentDisposition("attachment; filename*=ISO-8859-15''file%A4.txt");
      assert.equal(header.preferredFilename, 'file€.txt');
    });

    it('correctly decodes windows-1252 encoded filename', () => {
      let header = new ContentDisposition("attachment; filename*=windows-1252''file%80.txt");
      assert.equal(header.preferredFilename, 'file€.txt');
    });

    it('handles UTF-8 encoded filename correctly', () => {
      let header = new ContentDisposition("attachment; filename*=UTF-8''%E6%96%87%E4%BB%B6.txt");
      assert.equal(header.preferredFilename, '文件.txt');
    });

    it('falls back gracefully with a warning for unknown charsets', () => {
      let warn = console.warn;
      let warnWasCalled = false;
      console.warn = () => {
        warnWasCalled = true;
      };

      let header = new ContentDisposition("attachment; filename*=unknown-charset''file%FF.txt");

      assert.equal(header.preferredFilename, 'fileÿ.txt');
      assert.ok(warnWasCalled, 'console.warn should have been called');

      console.warn = warn;
    });
  });
});

