export { SuperHeadersInit, SuperHeaders, SuperHeaders as default } from './lib/super-headers.js';

export { ContentDisposition } from './lib/content-disposition.js';
export { ContentType } from './lib/content-type.js';
export { Cookie } from './lib/cookie.js';
export { SetCookie } from './lib/set-cookie.js';

export function capitalize(str: string): string {
  return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
}

export function isValidDate(date: unknown): boolean {
  return date instanceof Date && !isNaN(date.getTime());
}

export interface HeaderValue {
  toString(): string;
}

import { HeaderValue } from './header-value.js';
import { parseParams, quote } from './param-values.js';

/**
 * Represents the value of a `Cookie` HTTP header.
 */
export class Cookie implements HeaderValue, Iterable<[string, string]> {
  private cookies: Map<string, string>;

  constructor(initialValue?: string) {
    this.cookies = new Map();
    if (initialValue) {
      let params = parseParams(initialValue);
      for (let [name, value] of params) {
        this.cookies.set(name, value || '');
      }
    }
  }

  get(name: string): string | undefined {
    return this.cookies.get(name);
  }

  set(name: string, value: string): void {
    this.cookies.set(name, value);
  }

  delete(name: string): boolean {
    return this.cookies.delete(name);
  }

  has(name: string): boolean {
    return this.cookies.has(name);
  }

  clear(): void {
    this.cookies.clear();
  }

  [Symbol.iterator](): IterableIterator<[string, string]> {
    return this.cookies.entries();
  }

  entries(): IterableIterator<[string, string]> {
    return this.cookies.entries();
  }

  names(): IterableIterator<string> {
    return this.cookies.keys();
  }

  values(): IterableIterator<string> {
    return this.cookies.values();
  }

  forEach(
    callbackfn: (value: string, key: string, map: Map<string, string>) => void,
    thisArg?: any
  ): void {
    this.cookies.forEach(callbackfn, thisArg);
  }

  get size(): number {
    return this.cookies.size;
  }

  toString(): string {
    let pairs: string[] = [];

    for (let [name, value] of this.cookies) {
      pairs.push(`${name}=${quote(value)}`);
    }

    return pairs.join('; ');
  }
}

import { HeaderValue } from './header-value.js';
import { parseParams, quote } from './param-values.js';
import { capitalize, isValidDate } from './utils.js';

type SameSiteValue = 'Strict' | 'Lax' | 'None';

/**
 * Represents the value of a `Set-Cookie` HTTP header.
 */
export class SetCookie implements HeaderValue {
  public domain?: string;
  public expires?: Date;
  public httpOnly?: true;
  public maxAge?: number;
  public name?: string;
  public path?: string;
  public sameSite?: SameSiteValue;
  public secure?: true;
  public value?: string;

  constructor(initialValue?: string) {
    if (initialValue) {
      let params = parseParams(initialValue);
      if (params.length > 0) {
        this.name = params[0][0];
        this.value = params[0][1];

        for (let [key, value] of params.slice(1)) {
          switch (key.toLowerCase()) {
            case 'domain':
              this.domain = value;
              break;
            case 'expires': {
              if (typeof value === 'string') {
                let v = new Date(value);
                if (isValidDate(v)) this.expires = v;
              }
              break;
            }
            case 'httponly':
              this.httpOnly = true;
              break;
            case 'max-age': {
              if (typeof value === 'string') {
                let v = parseInt(value, 10);
                if (!isNaN(v)) this.maxAge = v;
              }
              break;
            }
            case 'path':
              this.path = value;
              break;
            case 'samesite':
              if (typeof value === 'string' && /strict|lax|none/i.test(value)) {
                this.sameSite = capitalize(value) as SameSiteValue;
              }
              break;
            case 'secure':
              this.secure = true;
              break;
          }
        }
      }
    }
  }

  toString(): string {
    if (!this.name) {
      return '';
    }

    let parts = [`${this.name}=${quote(this.value || '')}`];

    if (this.domain) {
      parts.push(`Domain=${this.domain}`);
    }
    if (this.path) {
      parts.push(`Path=${this.path}`);
    }
    if (this.expires) {
      parts.push(`Expires=${this.expires.toUTCString()}`);
    }
    if (this.maxAge) {
      parts.push(`Max-Age=${this.maxAge}`);
    }
    if (this.secure) {
      parts.push('Secure');
    }
    if (this.httpOnly) {
      parts.push('HttpOnly');
    }
    if (this.sameSite) {
      parts.push(`SameSite=${this.sameSite}`);
    }

    return parts.join('; ');
  }
}

import { ContentDisposition } from './content-disposition.js';
import { ContentType } from './content-type.js';
import { Cookie } from './cookie.js';
import { canonicalHeaderName } from './header-names.js';
import { HeaderValue } from './header-value.js';
import { SetCookie } from './set-cookie.js';
import { isValidDate } from './utils.js';

const CRLF = '\r\n';
const SetCookieKey = 'set-cookie';

export type SuperHeadersInit =
  | SuperHeaders
  | Headers
  | [string, string | HeaderValue][]
  | Record<string, string | HeaderValue>;

/**
 * A drop-in replacement for JavaScript `Headers` with type-safe access.
 *
 * @example
 *
 * ```ts
 * let headers = new SuperHeaders();
 * headers.contentType = 'text/plain; charset=utf-8';
 * headers.contentType.mediaType; // 'text/plain'
 * headers.contentType.charset; // 'utf-8'
 *
 * headers.contentType.mediaType = 'text/html';
 * headers.get('Content-Type'); // 'text/html; charset=utf-8'
 * ```
 */
export class SuperHeaders extends Headers implements Iterable<[string, string]> {
  private map: Map<string, string | HeaderValue>;
  private setCookieValues: (string | SetCookie)[] = [];

  constructor(init?: string | SuperHeadersInit) {
    super();

    this.map = new Map();

    if (init) {
      if (typeof init === 'string') {
        let lines = init.split(CRLF);
        for (let line of lines) {
          let match = line.match(/^([^:]+):(.*)/);
          if (match) {
            this.append(match[1].trim(), match[2].trim());
          }
        }
      } else if (init instanceof SuperHeaders || Array.isArray(init)) {
        for (let [name, value] of init) {
          this.append(name, value);
        }
      } else if (init instanceof Headers) {
        init.forEach((value, name) => {
          this.append(name, value);
        });
      } else if (typeof init === 'object') {
        for (let name in init) {
          if (Object.prototype.hasOwnProperty.call(init, name)) {
            this.append(name, init[name]);
          }
        }
      }
    }
  }

  append(name: string, value: string | HeaderValue): void {
    let key = name.toLowerCase();
    if (key === SetCookieKey) {
      this.setCookieValues.push(value as string | SetCookie);
    } else {
      let existingValue = this.map.get(key);
      this.map.set(key, existingValue ? `${existingValue}, ${value}` : value);
    }
  }

  delete(name: string): void {
    let key = name.toLowerCase();
    if (key === SetCookieKey) {
      this.setCookieValues = [];
    } else {
      this.map.delete(key);
    }
  }

  get(name: string): string | null {
    let key = name.toLowerCase();
    if (key === SetCookieKey) {
      return this.setCookieValues.map((value) => value.toString()).join(', ');
    } else {
      let value = this.map.get(key);
      if (typeof value === 'string') {
        return value;
      } else if (value instanceof Date) {
        return value.toUTCString();
      } else if (value != null) {
        return value.toString();
      } else {
        return null;
      }
    }
  }

  getSetCookie(): string[] {
    return this.setCookieValues.map((value) => value.toString());
  }

  has(name: string): boolean {
    let key = name.toLowerCase();
    if (key === SetCookieKey) {
      return this.setCookieValues.length > 0;
    } else {
      return this.map.has(key);
    }
  }

  set(name: string, value: string | HeaderValue): void {
    let key = name.toLowerCase();
    if (key === SetCookieKey) {
      this.setCookieValues = [value as string | SetCookie];
    } else {
      this.map.set(key, value);
    }
  }

  *entries(): IterableIterator<[string, string]> {
    for (let [key] of this.map) {
      let stringValue = this.get(key);
      if (stringValue) {
        yield [key, stringValue];
      }
    }

    for (let value of this.setCookieValues) {
      let stringValue = value.toString();
      if (stringValue) {
        yield [SetCookieKey, stringValue];
      }
    }
  }

  *keys(): IterableIterator<string> {
    for (let [key] of this) {
      yield key;
    }
  }

  *values(): IterableIterator<string> {
    for (let [, value] of this) {
      yield value;
    }
  }

  [Symbol.iterator](): IterableIterator<[string, string]> {
    return this.entries();
  }

  forEach(
    callback: (value: string, key: string, parent: SuperHeaders) => void,
    thisArg?: any
  ): void {
    for (let [key, value] of this) {
      callback.call(thisArg, value, key, this);
    }
  }

  toString(): string {
    let lines: string[] = [];

    for (let [key, value] of this) {
      lines.push(`${canonicalHeaderName(key)}: ${value}`);
    }

    return lines.join(CRLF);
  }

  // Header-specific getters and setters

  get age(): number | undefined {
    return this.getNumberValue('age');
  }

  set age(value: string | number) {
    this.map.set('age', value);
  }

  get contentDisposition(): ContentDisposition {
    return this.getHeaderValue('content-disposition', ContentDisposition);
  }

  set contentDisposition(value: string | ContentDisposition) {
    this.map.set('content-disposition', value);
  }

  get contentLength(): number | undefined {
    return this.getNumberValue('content-length');
  }

  set contentLength(value: string | number) {
    this.map.set('content-length', value);
  }

  get contentType(): ContentType {
    return this.getHeaderValue('content-type', ContentType);
  }

  set contentType(value: string | ContentType) {
    this.map.set('content-type', value);
  }

  get cookie(): Cookie {
    return this.getHeaderValue('cookie', Cookie);
  }

  set cookie(value: string | Cookie) {
    this.map.set('cookie', value);
  }

  get date(): Date | undefined {
    return this.getDateValue('date');
  }

  set date(value: string | Date) {
    this.map.set('date', value);
  }

  get expires(): Date | undefined {
    return this.getDateValue('expires');
  }

  set expires(value: string | Date) {
    this.map.set('expires', value);
  }

  get ifModifiedSince(): Date | undefined {
    return this.getDateValue('if-modified-since');
  }

  set ifModifiedSince(value: string | Date) {
    this.map.set('if-modified-since', value);
  }

  get ifUnmodifiedSince(): Date | undefined {
    return this.getDateValue('if-unmodified-since');
  }

  set ifUnmodifiedSince(value: string | Date) {
    this.map.set('if-unmodified-since', value);
  }

  get lastModified(): Date | undefined {
    return this.getDateValue('last-modified');
  }

  set lastModified(value: string | Date) {
    this.map.set('last-modified', value);
  }

  get setCookie(): SetCookie[] {
    for (let i = 0; i < this.setCookieValues.length; i++) {
      let value = this.setCookieValues[i];
      if (typeof value === 'string') {
        this.setCookieValues[i] = new SetCookie(value);
      }
    }

    return this.setCookieValues as SetCookie[];
  }

  set setCookie(values: string | (string | SetCookie)[]) {
    if (typeof values === 'string') {
      this.setCookieValues = [values];
    } else {
      this.setCookieValues = values.slice(0);
    }
  }

  // helpers

  private getDateValue(key: string): Date | undefined {
    let value = this.map.get(key);
    if (value) {
      if (typeof value === 'string') {
        let date = new Date(value);
        if (isValidDate(date)) {
          this.map.set(key, date); // cache the parsed date
          return date;
        } else {
          this.map.delete(key); // bad value, remove it
        }
      } else if (value instanceof Date) {
        return value;
      } else {
        this.map.delete(key); // bad value, remove it
      }
    }
  }

  private getNumberValue(key: string): number | undefined {
    let value = this.map.get(key);
    if (value) {
      if (typeof value === 'string') {
        let v = parseInt(value, 10);
        if (!isNaN(v)) {
          this.map.set(key, v); // cache the parsed number
          return v;
        } else {
          this.map.delete(key); // bad value, remove it
        }
      } else if (typeof value === 'number') {
        return value;
      } else {
        this.map.delete(key); // bad value, remove it
      }
    }
  }

  private getHeaderValue<T extends HeaderValue>(
    key: string,
    ctor: new (initialValue?: string) => T
  ): T {
    let value = this.map.get(key);
    if (value) {
      if (typeof value === 'string') {
        let headerValue = new ctor(value);
        this.map.set(key, headerValue);
        return headerValue;
      } else {
        return value as T;
      }
    } else {
      let headerValue = new ctor();
      this.map.set(key, headerValue);
      return headerValue;
    }
  }
}

import { HeaderValue } from './header-value.js';
import { parseParams, quote } from './param-values.js';

/**
 * Represents the value of a `Content-Type` HTTP header.
 */
export class ContentType implements HeaderValue {
  public mediaType?: string;
  public boundary?: string;
  public charset?: string;

  constructor(initialValue?: string) {
    if (initialValue) {
      let params = parseParams(initialValue);
      if (params.length > 0) {
        this.mediaType = params[0][0];
        for (let [name, value] of params.slice(1)) {
          if (name === 'boundary') {
            this.boundary = value;
          } else if (name === 'charset') {
            this.charset = value;
          }
        }
      }
    }
  }

  toString(): string {
    if (!this.mediaType) {
      return '';
    }

    let parts = [this.mediaType];

    if (this.charset) {
      parts.push(`charset=${quote(this.charset)}`);
    }
    if (this.boundary) {
      parts.push(`boundary=${quote(this.boundary)}`);
    }

    return parts.join('; ');
  }
}

import { HeaderValue } from './header-value.js';
import { parseParams, quote } from './param-values.js';

/**
 * Represents the value of a `Content-Disposition` HTTP header.
 */
export class ContentDisposition implements HeaderValue {
  public type?: string;
  public filename?: string;
  public filenameSplat?: string;
  public name?: string;

  constructor(initialValue?: string) {
    if (initialValue) {
      let params = parseParams(initialValue);
      if (params.length > 0) {
        this.type = params[0][0];
        for (let [name, value] of params.slice(1)) {
          if (name === 'filename') {
            this.filename = value;
          } else if (name === 'filename*') {
            this.filenameSplat = value;
          } else if (name === 'name') {
            this.name = value;
          }
        }
      }
    }
  }

  get preferredFilename(): string | undefined {
    // From RFC 6266:
    // Many user agent implementations predating this specification do not understand the "filename*" parameter.
    // Therefore, when both "filename" and "filename*" are present in a single header field value, recipients SHOULD
    // pick "filename*" and ignore "filename". This way, senders can avoid special-casing specific user agents by
    // sending both the more expressive "filename*" parameter, and the "filename" parameter as fallback for legacy recipients.
    let filenameSplat = this.filenameSplat;
    if (filenameSplat) {
      let decodedFilename = decodeFilenameSplat(filenameSplat);
      if (decodedFilename) return decodedFilename;
    }

    return this.filename;
  }

  toString(): string {
    if (!this.type) {
      return '';
    }

    let parts = [this.type];

    if (this.name) {
      parts.push(`name=${quote(this.name)}`);
    }
    if (this.filename) {
      parts.push(`filename=${quote(this.filename)}`);
    }
    if (this.filenameSplat) {
      parts.push(`filename*=${quote(this.filenameSplat)}`);
    }

    return parts.join('; ');
  }
}

function decodeFilenameSplat(value: string): string | null {
  let match = value.match(/^([\w-]+)'([^']*)'(.+)$/);
  if (!match) return null;

  let [, charset, , encodedFilename] = match;

  let decodedFilename = percentDecode(encodedFilename);

  try {
    let decoder = new TextDecoder(charset);
    let bytes = new Uint8Array(decodedFilename.split('').map((char) => char.charCodeAt(0)));
    return decoder.decode(bytes);
  } catch (error) {
    console.warn(`Failed to decode filename from charset ${charset}:`, error);
    return decodedFilename;
  }
}

function percentDecode(value: string): string {
  return value.replace(/\+/g, ' ').replace(/%([0-9A-Fa-f]{2})/g, (_, hex) => {
    return String.fromCharCode(parseInt(hex, 16));
  });
}

const HeaderWordCasingExceptions: Record<string, string> = {
  ct: 'CT',
  etag: 'ETag',
  te: 'TE',
  www: 'WWW',
  x: 'X',
  xss: 'XSS',
};

export function canonicalHeaderName(name: string): string {
  return name
    .toLowerCase()
    .split('-')
    .map((word) => HeaderWordCasingExceptions[word] || word.charAt(0).toUpperCase() + word.slice(1))
    .join('-');
}

export function parseParams(input: string): [string, string | undefined][] {
  let regex = /(?:^|;)\s*([^=;\s]+)(\s*=\s*(?:"((?:[^"\\]|\\.)*)"|((?:[^;]|\\\;)+))?)?/g;
  let params: [string, string | undefined][] = [];

  let match;
  while ((match = regex.exec(input)) !== null) {
    let key = match[1].trim();

    let value: string | undefined;
    if (match[2]) {
      value = (match[3] || match[4] || '').replace(/\\(.)/g, '$1').trim();
    }

    params.push([key, value]);
  }

  return params;
}

export function quote(value: string): string {
  if (value.includes('"') || value.includes(';') || value.includes(' ')) {
    return `"${value.replace(/"/g, '\\"')}"`;
  }
  return value;
}
